<?php
namespace ZinCelestial\Platform\Recovery;use RuntimeException;use ZinCelestial\Platform\Workflow\Contracts\WorkflowRepositoryInterface;defined('ABSPATH')||exit;
final class RecoveryManager {public function __construct(private WorkflowRepositoryInterface $repo,private RecoveryAuthorization $auth,private $audit){}public function recover(string $run_id,int $site,int $actor,string $operation,string $nonce,array $token,int $version):void{if(!$this->auth->authorize($actor,$site,$run_id,$operation,$nonce))throw new RuntimeException('Recovery denied.');$claims=ReplayToken::verify($token,$site,$run_id,$version);$run=$this->repo->get($run_id);if(!$run||!in_array($run->status(),['failed','retrying'],true))throw new RuntimeException('Run is not recoverable.');call_user_func($this->audit,['event'=>'recovery_requested','site'=>$site,'run'=>sanitize_key($run_id),'operation'=>$operation,'actor'=>$actor,'jti'=>$claims['jti'],'at'=>time()]);if($operation==='resume')$run->retry();elseif($operation==='compensate')$run->compensate();else throw new RuntimeException('Replay creates a new immutable run and requires a factory.');}}
